/**
 * cloudControllerManager contains settings specific to the external Cloud Controller Manager (a.k.a. CCM or CPI).
 * When omitted, new nodes will be not tainted
 * and no extra initialization from the cloud controller manager is expected.
 * @export
 * @interface IoOpenshiftConfigV1InfrastructureStatusPlatformStatusExternalCloudControllerManager
 */
export interface IoOpenshiftConfigV1InfrastructureStatusPlatformStatusExternalCloudControllerManager {
    /**
     * state determines whether or not an external Cloud Controller Manager is expected to
     * be installed within the cluster.
     * https://kubernetes.io/docs/tasks/administer-cluster/running-cloud-controller/#running-cloud-controller-manager
     * 
     * Valid values are "External", "None" and omitted.
     * When set to "External", new nodes will be tainted as uninitialized when created,
     * preventing them from running workloads until they are initialized by the cloud controller manager.
     * When omitted or set to "None", new nodes will be not tainted
     * and no extra initialization from the cloud controller manager is expected.
     * @type {string}
     * @memberof IoOpenshiftConfigV1InfrastructureStatusPlatformStatusExternalCloudControllerManager
     */
    state?: IoOpenshiftConfigV1InfrastructureStatusPlatformStatusExternalCloudControllerManagerStateEnum;
}

/**
* @export
* @enum {string}
*/
export enum IoOpenshiftConfigV1InfrastructureStatusPlatformStatusExternalCloudControllerManagerStateEnum {
    Empty = '',
    External = 'External',
    None = 'None'
}

